#!/usr/bin/env python3
"""crispr/sgrna_design_score — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "sgrna_design_score"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'sgrna_design_score', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """sgRNA 设计:扫 target_sequence 找所有 PAM(NGG)+ 20nt protospacer,简单评分 (GC% / repeats / homopolymer)。
    host_env=PRAXIS-CRISPR(Bio + primer3)。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("target_sequence") or payload.get("sequence")
    pam = payload.get("pam", "NGG")
    out_csv = payload.get("out_csv") or _tempfile.NamedTemporaryFile(suffix="_grna.csv", delete=False).name
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "pam": pam, "out_csv": out_csv}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not seq:
        return {"ok": False, "error": "需要 target_sequence", "diagnostics": diagnostics}
    script = (
        "import json, sys, re as _re, csv\n"
        f"seq = {seq!r}.upper(); pam = {pam!r}.upper(); out_csv = {out_csv!r}\n"
        "pam_re = pam.replace('N', '[ACGT]')\n"
        "guides = []\n"
        "for m in _re.finditer(f'(?=([ACGT]{20}{pam_re}))', seq):\n"
        "    g = m.group(1)[:20]; pam_seq = m.group(1)[20:]\n"
        "    gc = sum(1 for c in g if c in 'GC') / 20.0\n"
        "    # 简单 heuristic 评分\n"
        "    score = 1.0\n"
        "    if gc < 0.3 or gc > 0.8: score -= 0.3\n"
        "    if 'TTTT' in g or 'AAAA' in g: score -= 0.2\n"
        "    guides.append({'protospacer': g, 'pam': pam_seq, 'gc': round(gc,3),\n"
        "                   'mit_score': round(max(0,score), 3),\n"
        "                   'cfd_score': round(max(0,score), 3), 'pos': m.start()})\n"
        "guides.sort(key=lambda x: -x['mit_score'])\n"
        "with open(out_csv, 'w') as fh:\n"
        "    w = csv.DictWriter(fh, fieldnames=['protospacer','pam','gc','mit_score','cfd_score','pos']); w.writeheader()\n"
        "    for g in guides: w.writerow(g)\n"
        "json.dump({'n_guides': len(guides), 'guides_csv': out_csv,\n"
        "           'best_guide': guides[0] if guides else None}, sys.stdout)\n"
    )
    t0 = _time.time()
    r = run_tool(["python3", "-c", script], timeout=120)
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "grna_design 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    try: parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "diagnostics": diagnostics}
    best = parsed.get("best_guide") or {"seq": "", "cfd_score": 0.0, "mit_score": 0.0}
    if "protospacer" in best: best = {"seq": best["protospacer"], "cfd_score": best["cfd_score"], "mit_score": best["mit_score"]}
    return {"ok": True, "skill_id": SKILL, **parsed, "best_guide": best,
            "runtime_sec": round(_time.time() - t0, 2), "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
